37	export function getResponsesApiCompactionThreshold(configService: IConfigurationService, expService: IExperimentationService, endpoint: IChatEndpoint): number | undefined {
38		const contextManagementEnabled = configService.getExperimentBasedConfig(ConfigKey.ResponsesApiContextManagementEnabled, expService) && !modelsWithoutResponsesContextManagement.has(endpoint.family);
39		if (!contextManagementEnabled) {
40			return undefined;
41		}
42	
43		return endpoint.modelMaxPromptTokens > 0
44			? Math.floor(endpoint.modelMaxPromptTokens * 0.9)
45			: 50000;
46	}
