18	/**
19	 * Agent configuration for building .agent.md content.
20	 * Shared by PlanAgentProvider, AskAgentProvider, and other custom agents.
21	 */
22	export interface AgentConfig {
23		readonly name: string;
24		readonly description: string;
25		readonly argumentHint: string;
26		readonly tools: string[];
27		readonly model?: string | readonly string[];
28		readonly target?: string;
29		readonly disableModelInvocation?: boolean;
30		readonly userInvocable?: boolean;
31		readonly agents?: string[];
32		readonly handoffs?: AgentHandoff[];
33		readonly body: string;
34	}
35	
36	/**
37	 * Default read-only tools shared by Plan, Ask, and other agents.
38	 * These tools can only inspect the workspace — they never modify it.
39	 */
40	export const DEFAULT_READ_TOOLS: readonly string[] = [
41		'search',
42		'read',
43		'web',
44		'vscode/memory',
45		'github/issue_read',
46		'github.vscode-pull-request-github/issue_fetch',
47		'github.vscode-pull-request-github/activePullRequest',
48		'execute/getTerminalOutput',
49		'execute/testFailure'
50	];
