74		async provideCustomAgents(
75			_context: unknown,
76			_token: vscode.CancellationToken
77		): Promise<vscode.ChatResource[]> {
78			// Build config with settings-based customization
79			const config = this.buildCustomizedConfig();
80	
81			// Generate .agent.md content
82			const content = buildAgentMarkdown(config);
83	
84			// Write to cache file and return URI
